import{d as c,C as t,o as u,c as g,j as a,a as s,E as n,a3 as m}from"./chunks/framework.Q4yG9rk_.js";const f=JSON.parse('{"title":"道德经第五十五章","description":"从赤子的柔弱与精和，到知常和强壮之戒，辨明朘作与王注全作的差异。","frontmatter":{"title":"道德经第五十五章","description":"从赤子的柔弱与精和，到知常和强壮之戒，辨明朘作与王注全作的差异。","category":"guide","aliases":["道德经第五十五章","老子第五十五章","dao de jing chapter 55"],"source":["王弼《道德真经注》卷三"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-55.md","filePath":"daoism/dao-de-jing/chapter-55.md","lastUpdated":1794189804000}'),b={name:"daoism/dao-de-jing/chapter-55.md"},_=c({...b,setup(p){const o=[{id:"infant-and-unharmed-wholeness",label:"含德之厚，比于赤子",showLabel:!0,sentences:[["含德之",{text:"厚",glossary:"hou"},"，比于",{text:"赤子",glossary:"chizi"},"。毒虫不",{text:"螫",glossary:"shi"},"，猛兽不",{text:"据",glossary:"ju"},"，",{text:"攫鸟",glossary:"jueniao"},"不",{text:"搏",glossary:"bo"},"。"]],note:["【白话】含德深厚的人，可以比于初生婴儿：毒虫不蜇伤他，猛兽不攫取他，猛禽不扑击他。这些强烈的形象写不争、不犯而保全的状态。","【王弼注择要】「赤子无求无欲，不犯众物。」注又说「含德之厚者不犯于物，故无物以损其全也」，以不犯物解释无所损。","【读法】据、搏在此取攫持、扑击义；所据经文开头作蜂虿虺蛇，本站保留毒虫。这里的赤子取象不等于婴儿实际不会受虫兽伤害，照料和保护仍有必要。"]},{id:"softness-and-a-firm-grip",label:"骨弱筋柔而握固",showLabel:!0,sentences:[["骨弱筋柔而握固。"]],note:["【白话】骨骼柔弱、筋脉柔软，抓握却能牢固。经文从赤子的身体取象，说明柔弱与保全、稳固并不互相排斥。","【王弼注择要】「以柔弱之故，故握能周固。」王弼将握固归于柔弱的作用，不用外在刚强解释。","【读法】握固可与第五十二章守柔曰强相参；这是本章的取象和推论，不将它扩成越弱就越有力量的普遍生理定律。"]},{id:"spontaneity-and-vital-essence",label:"精之至也",showLabel:!0,sentences:[["未知",{text:"牝牡",glossary:"pinmu"},"之合而",{text:"朘",glossary:"zui"},"作，",{text:"精",glossary:"jing"},"之至也。"]],note:["【白话】按本站现文：还不知道雌雄交合，男婴的生殖器却能自然勃起，经文用这来说明精气充足、自然发动，不由知欲催使。","【校读】本站作朘作，朘在这里按男孩生殖器义读 zuī；所据录文作全作，不能把两种字面当成一致。原稿 juān 的标音在此改正，并在篇末列出字音参考。","【王弼注择要】所据全作下注「作，长也」；又说「无物以损其身，故能全长也」，沿全而生长的方向解释。此注按其录文另列，不充作朘字训诂。","【读法】精在本站句中取生命精气，与第二十一章精微实质义分开；两种读法都处在不以争欲损其全的章内脉络，不作可量化的生理结论。"]},{id:"crying-and-harmony",label:"终日号而不嗄",showLabel:!0,sentences:[["终日",{text:"号",glossary:"hao"},"而不",{text:"嗄",glossary:"sha"},"，",{text:"和",glossary:"he"},"之至也。"]],note:["【白话】整天啼哭却不声嘶，经文用这来说明和气充足。重点在声音自发，而非怀着争求之心强使其声。","【王弼注择要】「无争欲之心，故终日出声而不嗄也。」注从无争欲解释和之至。","【读法】号读 háo，为啼哭；嗄为声嘶。此为经文与古注取象，不能据此断言婴儿长哭无碍，也不应忽略实际照料和异常征象。"]},{id:"harmony-constancy-and-clarity",label:"知和曰常，知常曰明",showLabel:!0,sentences:[["知",{text:"和",glossary:"he"},"曰常，",{text:"知常",glossary:"zhichang"},"曰明，"]],note:["【白话】认识和合的道理，叫作知常；认识常道，叫作明。前面的赤子、柔弱、精与和，在这里被提升为对常道的认识。","【王弼注择要】「物以和为常，故知和则得常也。」知常曰明下注又以「无形不可得而见曰明也」解释这种明，不只取外在显耀。","【读法】和在本章连无争欲、精气自全理解，不机械套作所有差异都消失。常也不是要求一切现状不变，而是所依的道之常。"]},{id:"forced-increase-and-driven-qi",label:"益生曰祥，心使气曰强",showLabel:!0,sentences:[[{text:"益生",glossary:"yisheng"},"曰",{text:"祥",glossary:"xiang"},"，心使气曰",{text:"强",glossary:"qiang"},"。"]],note:["【白话】刻意增益生命的过度追求，会显出不祥的警兆；以心意强行驱使气，就成了强作。此处转而警戒对生命的强加。","【王弼注择要】「生不可益，益之则夭也。」心使气下注「心宜无有，使气则强」，使前句的增益与后句的强驱相接。","【读法】祥字本可说征兆，本页循益之则夭读作警兆，不按吉祥直译。强读 qiáng，取强作义，与第五十二章守柔所得的强健分开；这不是要求放弃营养、医疗，或提供强控呼吸的练法。"]},{id:"overstrength-and-early-ending",label:"物壮则老",showLabel:!0,sentences:[["物",{text:"壮",glossary:"zhuang"},"则老，谓之不道，不道早",{text:"已",glossary:"yi"},"。"]],note:["【白话】事物走向过度强壮、逞强，便转向衰老，这称为不合于道；不合于道的，便会过早止息。","【读法】本章所据此句未另见独立王注，可连前段益之则夭、使气则强读，并与第三十章同句相参。壮在这里另列生命强盛过度义，不只沿用武力暴兴的语境。","【读法】已为停止，早已在此是过早终止，不作现代副词早就。经句警戒强作难久，不将一切年老、疾病或死亡都判为个人失道。"]}],r=[{id:"hou",term:"厚",sense:2},{id:"chizi",term:"赤子",sense:1},{id:"shi",term:"螫",sense:1},{id:"ju",term:"据",sense:1},{id:"jueniao",term:"攫鸟",sense:1},{id:"bo",term:"搏",sense:2},{id:"pinmu",term:"牝牡",sense:1},{id:"zui",term:"朘",sense:1},{id:"jing",term:"精",sense:2},{id:"hao",term:"号",sense:1},{id:"sha",term:"嗄",sense:1},{id:"he",term:"和",sense:1},{id:"zhichang",term:"知常",sense:1},{id:"yisheng",term:"益生",sense:1},{id:"xiang",term:"祥",sense:1},{id:"qiang",term:"强",sense:5,pinyin:"qiáng"},{id:"zhuang",term:"壮",sense:2},{id:"yi",term:"已",sense:1}];return(x,e)=>{const i=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return u(),g("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第五十五章",tabindex:"-1"},[s("道德经第五十五章 "),a("a",{class:"header-anchor",href:"#道德经第五十五章","aria-label":'Permalink to "道德经第五十五章"'},"​")],-1)),n(i,{title:"含德之厚为什么比于赤子",summary:"本章以赤子的柔弱、无争与精和描写含德之厚，再由知和知常转向益生、使气与壮老之戒。王弼以不犯于物、不以争欲损其全来解释；本站朘作与所据全作不同，白话与古注分开处理。",points:[{label:"先读",text:"赤子是德厚、柔弱不争的取象，虫兽无害的经句不作现实免伤保证。"},{label:"再辨",text:"本站朘作按生殖器自然勃起之象释，朘读 zuī；所据录文全作与作长也另行说明。"},{label:"后看",text:"祥循益之则夭的王注取警兆义，心使气的强与守柔的强健分辨。"}],hint:"螫读 shì，攫读 jué，朘在本页读 zuī，号读 háo，嗄读 shà；祥在此不按日常吉祥义直译。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[s("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),n(l,{sections:o,glossary:r}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[s("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),n(d,{lines:[{text:"含德之厚，比于赤子。",tone:"柔弱无争的取象",guide:"由赤子理解不自损其全，保留实际养护的需要。"},{text:"知和曰常，知常曰明，",tone:"由和认识常道",guide:"接续精与和，不以外显强壮当作唯一尺度。"},{text:"益生曰祥，心使气曰强。",tone:"从和转向强作之戒",guide:"祥循王注取警兆，心使气的强与守柔的强健分开。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[s("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),n(h,{items:r}),e[4]||(e[4]=m('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-赤子的几种形象共同说明什么" tabindex="-1">象：赤子的几种形象共同说明什么？ <a class="header-anchor" href="#象-赤子的几种形象共同说明什么" aria-label="Permalink to &quot;象：赤子的几种形象共同说明什么？&quot;">​</a></h3><p>虫兽不犯、柔弱握固、精气自发与啼哭不嗄，都被用来说明不依争欲而保全的状态。它们服务于含德之厚的取象，不是为婴儿建立免伤或无需求助的生理模型。</p><h3 id="理-为什么说完精和-又警戒益生与使气" tabindex="-1">理：为什么说完精和，又警戒益生与使气？ <a class="header-anchor" href="#理-为什么说完精和-又警戒益生与使气" aria-label="Permalink to &quot;理：为什么说完精和，又警戒益生与使气？&quot;">​</a></h3><p>前半写自发而全，后半写出于心意的强增与强驱。依王弼，若越想增加生命，反而越以造作损其自然，就会从和走向夭折与早止的风险。</p><h3 id="用-今天怎样理解这段养生之戒" tabindex="-1">用：今天怎样理解这段养生之戒？ <a class="header-anchor" href="#用-今天怎样理解这段养生之戒" aria-label="Permalink to &quot;用：今天怎样理解这段养生之戒？&quot;">​</a></h3><p>可以反省某种追求健康的做法，是否反而造成持续透支或强迫。古代气论不能直接转成现代医疗方案，实践仍应依据身体实际状况与可靠的专业判断。</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p><strong>养护不只看增加了什么。</strong> 更多补养、更强训练或更密集的管理，并不自动带来更好的状态。留意是否适合实际需要，也给休息和恢复留下位置。</p><p><strong>区分安稳的力量与强迫的控制。</strong> 守柔可以保留回应能力，以心强驱却可能只为追求一个理想表现。判断一种方法，应观察它是否使人更能稳定生活，而非更怕偏离指标。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><p>留给自己的续读问题：我追求的强健，是更能安稳回应生活，还是必须不断控制自己才能维持的表现？哪些增加和强迫，已经开始损害本来要照料的生命？</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><ul><li>正文与标点沿本站保留，据卷三 015a–015b 电子录文核对；本站毒虫，录文作蜂虿虺蛇。</li><li>本站朘作，录文作全作，王注以作长也、全长解释后者；本页分别翻译与说明，不以全长之注冒作朘字的直接训释。</li><li>朘取男孩生殖器义，读 zuī，纠正原稿 juān；其发动作无知欲而自然之象。精另列生命精气义，搏另列扑击义，厚、强、壮均按本章与旧义分开。</li><li>祥循益之则夭取警兆义；已取止息义。经注的虫兽、声音、精气取象与本站现代健康类比分开，不作现实免伤、养生功效或医疗结论。</li></ul><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_003.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷三 HFL 本电子录文，015a–015b</a>。</p><p>字音参考：<a href="https://www.zdic.net/hans/%E6%9C%98" target="_blank" rel="noreferrer">汉典「朘」条</a>，本页采用 zuī 的男孩生殖器义，与 juān 的缩减、剥削义分开。</p>',16))])}}});export{f as __pageData,_ as default};
